    vector<int> data;
public:
    void push(int v) { data.push_back(v); }
    bool pop() {                              // returns false instead of crashing
        if (data.empty()) return false;
        data.pop_back();
        return true;
    }
    bool top(int& out) const {                // guarded read
        if (data.empty()) return false;
        out = data.back();
        return true;
    }
    bool empty() const { return data.empty(); }
    int size() const { return (int)data.size(); }
};

