class ArrayStack:
    def __init__(self):
        self._data = []

    def push(self, v) -> None:
        self._data.append(v)

    def pop(self):
        """Returns None on empty instead of raising -- guarded, not crashing."""
        return self._data.pop() if self._data else None

    def top(self):
        return self._data[-1] if self._data else None

    def empty(self) -> bool:
        return not self._data

    def size(self) -> int:
        return len(self._data)

