    struct Node { int val; Node* next; };
    Node* head = nullptr;
    int count = 0;
public:
    void push(int v) { head = new Node{v, head}; ++count; }   // insert at HEAD
    bool pop() {
        if (!head) return false;
        Node* doomed = head;
        head = head->next;                                    // delete at HEAD
        delete doomed;
        --count;
        return true;
    }
    bool top(int& out) const {
        if (!head) return false;
        out = head->val;
        return true;
    }
    bool empty() const { return head == nullptr; }
    int size() const { return count; }
};

