class LinkedStack:
    class _Node:
        __slots__ = ("val", "next")
        def __init__(self, val, nxt):
            self.val = val
            self.next = nxt

    def __init__(self):
        self._head = None
        self._count = 0

    def push(self, v) -> None:
        self._head = LinkedStack._Node(v, self._head)   # insert at HEAD
        self._count += 1

    def pop(self):
        if self._head is None:
            return None
        val = self._head.val
        self._head = self._head.next                    # delete at HEAD
        self._count -= 1
        return val

    def top(self):
        return self._head.val if self._head else None

    def empty(self) -> bool:
        return self._head is None

    def size(self) -> int:
        return self._count

