// DELIBERATELY WASTEFUL: front only ever moves right, so cells behind it are
// lost forever. After capacity operations the queue is "full" while holding
// nothing. That pain is exactly what the circular queue fixes.
class DriftingQueue {
    vector<int> data;
    int front = 0, back = 0;     // [front, back) is the live window
public:
    explicit DriftingQueue(int capacity) : data(capacity) {}

    bool enqueue(int v) {
        if (back == (int)data.size()) return false;   // no room LEFT, even if space exists
        data[back++] = v;
        return true;
    }
    bool dequeue(int& out) {
        if (front == back) return false;              // empty
        out = data[front++];                          // front NEVER goes back
        return true;
    }
    bool empty() const { return front == back; }
    int size() const { return back - front; }
    int wastedCells() const { return front; }         // measurable proof of the leak
};

