class DriftingQueue:
    """DELIBERATELY WASTEFUL: front only ever moves right, so cells behind it
    are lost forever. After capacity-many enqueues the queue reports full while
    holding nothing. That pain is what the circular queue fixes."""

    def __init__(self, capacity: int):
        self._data = [None] * capacity
        self._front = 0
        self._back = 0                # [front, back) is the live window

    def enqueue(self, v) -> bool:
        if self._back == len(self._data):
            return False              # no room LEFT, even if space exists
        self._data[self._back] = v
        self._back += 1
        return True

    def dequeue(self):
        if self._front == self._back:
            return None               # empty
        v = self._data[self._front]
        self._front += 1              # front NEVER goes back
        return v

    def empty(self) -> bool:
        return self._front == self._back

    def size(self) -> int:
        return self._back - self._front

    def wasted_cells(self) -> int:
        return self._front            # measurable proof of the leak

