    class _Node:
        __slots__ = ("val", "next")
        def __init__(self, val):
            self.val = val
            self.next = None

    def __init__(self):
        self._head = None
        self._tail = None
        self._count = 0

    def enqueue(self, v) -> None:
        node = LinkedQueue._Node(v)
        if self._tail is None:
            self._head = self._tail = node    # EMPTY: set BOTH
        else:
            self._tail.next = node
            self._tail = node
        self._count += 1

    def dequeue(self):
        if self._head is None:
            return None
        v = self._head.val
        self._head = self._head.next
        if self._head is None:
            self._tail = None                 # LAST element: reset tail too
        self._count -= 1
        return v

    def empty(self) -> bool:
        return self._head is None

    def size(self) -> int:
        return self._count

