bool balancedSingle(const string& s) {
    int depth = 0;
    for (char c : s) {
        if (c == '(') ++depth;
        else if (c == ')') {
            if (--depth < 0) return false;   // closed one that was never opened
        }
    }
    return depth == 0;                        // nothing left dangling
}

