def balanced_single(s: str) -> bool:
    depth = 0
    for c in s:
        if c == "(":
            depth += 1
        elif c == ")":
            depth -= 1
            if depth < 0:
                return False      # closed one that was never opened
    return depth == 0             # nothing left dangling

