string toBinary(int n) {
    if (n == 0) return "0";               // the loop emits nothing for 0
    bool neg = n < 0;
    long long v = llabs((long long)n);
    stack<int> st;
    while (v) { st.push((int)(v % 2)); v /= 2; }   // LSB pushed first
    string out;
    while (!st.empty()) { out += char('0' + st.top()); st.pop(); }   // MSB pops first
    return neg ? "-" + out : out;
}

