// O(n^2) BY DESIGN: for each element, walk right until something bigger.
// On [5,4,3,2,1] this scans n-i elements for every i -- about n^2/2 comparisons.
vector<int> nextGreaterBrute(const vector<int>& a) {
    int n = (int)a.size();
    vector<int> out(n, -1);
    for (int i = 0; i < n; ++i)
        for (int j = i + 1; j < n; ++j)
            if (a[j] > a[i]) { out[i] = a[j]; break; }
    return out;
}

