def next_greater_brute(a: list) -> list:
    """O(n^2) BY DESIGN: for each element, walk right until something bigger.
    On [5,4,3,2,1] this scans n-i elements per i -- about n^2/2 comparisons."""
    n = len(a)
    out = [-1] * n
    for i in range(n):
        for j in range(i + 1, n):
            if a[j] > a[i]:
                out[i] = a[j]
                break
    return out

